WITH event_rows AS (SELECT b.mktcode,b.tgtcode,b.bizdate,b.lastPx / 10000.0 AS price,MIN(b.lastPx / 10000.0) OVER(PARTITION BY b.mktcode,b.tgtcode ORDER BY b.bizdate ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS low_all,MAX(b.lastPx / 10000.0) OVER(PARTITION BY b.mktcode,b.tgtcode ORDER BY b.bizdate ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS high_all FROM `newzl`.`hsj_stock_hq_basic` b) SELECT mktcode,tgtcode,bizdate FROM event_rows WHERE bizdate='2026-04-14' AND price>low_all AND price<high_all AND (price-low_all)/NULLIF(high_all-low_all,0)<=0.25;
